@spec arrange_view_spec  src=tests/specs/arrange_view_spec.lua  loc=1142  cases=66
@exercises configManager (h.cm), arrangeManager (am), commandManager (h.cmgr), arrangeView (av)
@surface   cm:set, am:resizeTake, am:tracksTakes, cmgr:push, av:cursorRow, av:cursorCol, av:setCursor, av:setBeatPerRow, av:setCursorAt, av:setGridSize, av:scroll, av:scrollBy, av:setMaxCol, av:beatPerRow, cm:get, av:rowToQN, av:paletteSlot, av:setPaletteSlot, av:tracksTakes, am:deleteTake, av:pruneSlots, av:trackSlots, av:focus, av:setFocus, cmgr:invoke, av:lassoCandidate, av:selectionSet, av:isSelected, av:selectBand, cmgr:pop, av:dropBand, av:setSelection, av:addToSelection, av:toggleSelected, av:dragCandidate, av:commitDrag, am:loopRangeQN, am:editCursorQN, am:trimHead, av:cursorTake, av:qnToRow
@harness   mk, reaper:setTrackName, reaper:addItem, reaper:setProjectTracks, reaper.GetSetRepeat

# Intent
  arrangeView: in-memory cursor/scroll + persisted beatPerRow, mirroring
  the trackerView/editCursor split (cursor is transient, density persists).

# Helpers
  @fn mkAv(harness)  @ 7-13
  @fn mkArrange(harness, items)  @ 17-38
      -- Build an av over a fake project. items: list of {track, name, pos, len?}.
      -- Tracks are created in first-seen order; beatPerRow is 1 (1 row = 1 QN).
  @fn takeAt(list, startQN)  @ 40-42
  @fn mkTrimmable(harness)  @ 46-53
      -- One four-row take at rows 2..5, with four rows of source left over: enough
      -- room for the head to walk in and for the tail to grow.

# Cases
  @case 'cursor defaults to (0,0); setCursor clamps negatives and floors'  [harness]  @ 74-82
  @case 'setCursorAt lands the caret on the row holding a project QN'  [harness]  @ 87-94
  @case 'scroll defaults to (0,0); setGridSize alone does not move scroll'  [harness]  @ 98-104
  @case 'cursor moving below the visible band scrolls down to follow'  [harness]  @ 108-115
  @case 'cursor moving above the visible band scrolls up to follow'  [harness]  @ 119-127
  @case 'horizontal follow tracks cursorCol against gridCols'  [harness]  @ 131-141
  @case 'setGridSize shrinking the viewport re-follows the cursor in place'  [harness]  @ 145-156
  @case 'scrollBy pans the viewport without moving the cursor'  [harness]  @ 160-169
  @case 'scrollBy clamps to >= 0 and cursor-nav re-follows the cursor'  [harness]  @ 173-184
  @case 'scroll-right stops once the last column is fully visible'  [harness]  @ 188-196
  @case 'a same-dims setGridSize after a wheel-scroll leaves scroll alone'  [harness]  @ 200-208
  @case 'beatPerRow defaults to cm value; setter clamps minimum'  [harness]  @ 212-221
  @case 'setBeatPerRow holds the cursor QN (zoom anchors on cursor) and clamps max'  [harness]  @ 225-237
  @case 'paletteSlot defaults nil; setter clamps to 0..61; nil clears'  [harness]  @ 241-255
  @case 'a prune takes the palette focus down with the slot it lost'  [harness]  @ 259-271
  @case 'a prune leaves the palette focus alone when its slot still stands'  [harness]  @ 275-286
  @case 'focus defaults nil; setFocus stores an opaque handle, nil clears'  [harness]  @ 290-299
  @case 'no selection + on-screen cursor: edit acts on the cursor take, leaves it unselected'  [harness]  @ 303-319
  @case 'no selection + off-screen cursor: an edit is a no-op'  [harness]  @ 323-339
  @case 'a held selection wins over the cursor take'  [harness]  @ 343-362
  @case 'lasso selects every take whose span intersects the swept rect'  [harness]  @ 366-382
  @case 'Shift+arrow selects every take the anchor-to-cursor rect covers'  [harness]  @ 386-399
  @case 'Shift+arrow sideways widens the rect into the next column'  [harness]  @ 403-414
  @case 'Shift+arrow back toward the anchor drops what it uncovers'  [harness]  @ 418-432
  @case 'a plain cursor move ends the run, so the next Shift+arrow re-anchors'  [harness]  @ 436-448
  @case 'a bare cursor move clears the selection'  [harness]  @ 452-462
  @case 'Home clears the selection like any other bare nav'  [harness]  @ 466-476
  @case 'Tab walks down the column, stopping at each start and each free row after a take'  [harness]  @ 480-498
  @case 'abutting takes collapse their shared boundary to one Tab stop'  [harness]  @ 502-513
  @case 'Shift+Tab walks back up, snapping to the start of the take it is inside'  [harness]  @ 517-531
  @case 'Tab only sees the takes in the cursor column'  [harness]  @ 535-548
  @case 'Tab clears the selection like any other bare nav'  [harness]  @ 552-563
  @case 'an edit's own cursor advance keeps the selection'  [harness]  @ 567-578
  @case 'the pooled duplicate clears the selection and lands the caret on the copy'  [harness]  @ 582-599
  @case 'the band stands through a run and comes down on the next command'  [harness]  @ 603-621
  @case 'a click takes the band down without waiting for a command'  [harness]  @ 625-636
  @case 'dropBand takes the band down and pops its scope'  [harness]  @ 640-650
  @case 'a multi-selection deletes every selected take in one pass'  [harness]  @ 654-668
  @case 'nudge refuses entirely when any selected take is blocked'  [harness]  @ 672-689
  @case 'nudge slides a contiguous selected block without self-collision'  [harness]  @ 693-708
  @case 'a single-target command no-ops on a multi-selection'  [harness]  @ 712-725
  @case 'arrangeClearSelection empties the selection'  [harness]  @ 729-740
  @case 'addToSelection unions handles without duplicating a present one'  [harness]  @ 744-758
  @case 'toggleSelected adds an absent handle and removes a present one'  [harness]  @ 762-775
  @case 'group drag slides the whole selection by one delta'  [harness]  @ 779-795
  @case 'group drag refuses when a member would hit an outside take'  [harness]  @ 799-812
  @case 'group drag with Alt duplicates the block and reselects the copies'  [harness]  @ 816-834
  @case 'loop to item brackets the take under the arrange cursor'  [harness]  @ 840-856
  @case 'loop to item takes the selection over the cursor, and spans a block'  [harness]  @ 860-877
  @case 'a cursor-driven replace leaves nothing selected'  [harness]  @ 881-893
  @case 'a replace of a selected take hands the selection to the replacement'  [harness]  @ 897-912
  @case 'a replace of a selection away from the cursor leaves the cursor alone'  [harness]  @ 916-928
  @case 'with advance-by-length armed, a drop advances by the take it placed'  [harness]  @ 934-947
  @case 'advance-by-length reads the clipped length, not the slot length'  [harness]  @ 951-964
  @case 'a second Ctrl-` puts the drop advance back on arrangeAdvanceBy'  [harness]  @ 968-982
  @case 'the caret on a start row moves the head down, holding the end still'  [harness]  @ 989-998
  @case 'the split key cuts the take at the caret and leaves the caret on the lower half'  [harness]  @ 1002-1012
  @case 'a split on the start row has nothing to cut'  [harness]  @ 1016-1022
  @case 'the caret off the start row moves the tail, leaving the head alone'  [harness]  @ 1026-1035
  @case 'Up on the start row hands back a row of head, taking the caret with it'  [harness]  @ 1039-1049
  @case 'a head at the origin refuses to grow, and the caret holds'  [harness]  @ 1053-1062
  @case 'the take under the cursor carries the source its box hides'  [harness]  @ 1066-1077
  @case 'a head trim is floored at one rendered row'  [harness]  @ 1081-1091
  @case 'a tail shrink never parks the caret on the head row'  [harness]  @ 1095-1108
  @case 'the armed edge is decided once, from the take the caret stands on'  [harness]  @ 1112-1127
  @case 'qnToRow / rowToQN are inverses through beatPerRow'  [harness]  @ 1131-1140

